import com.oracle.e1.common.OrchestrationAttributes;
import java.text.SimpleDateFormat;
import groovy.json.*;

HashMap<String, Object> main(OrchestrationAttributes orchAttr, HashMap inputMap)
{
HashMap<String, Object> returnMap = new HashMap<String, Object>();

String CreateStatus = (String)inputMap.get("CreateStatus");
String CreateAction = (String) inputMap.get("CreateAction");
String CreateErrors = (String) inputMap.get("CreateErrors");
String UpdateStatus = (String)inputMap.get("UpdateStatus");
String UpdateAction = (String) inputMap.get("UpdateAction");
String UpdateErrors = (String) inputMap.get("UpdateErrors");    

String Status = "FAILURE";
String Action = "UNKNOWN";
String Errors = "";

//Only one set of variables should be populated, so whichever one is, use that one.

if(CreateStatus!=null && !CreateStatus.trim().isEmpty()) //Create
{
Action = CreateAction;
Status = CreateStatus;
Errors = CreateErrors;
}    

if(UpdateStatus!=null && !UpdateStatus.trim().isEmpty()) //Update
{
Action = UpdateAction;
Status = UpdateStatus;
Errors = UpdateErrors;
}        

returnMap.put("Action", Action);        
returnMap.put("Status", Status);   
returnMap.put("Errors", Errors);   

return returnMap;
}
